from pathlib import Path
import json,sys,shutil,zipfile,hashlib
import numpy as np,cv2
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
B=Path(__file__).resolve().parent;ROOT=B.parents[1];sys.path.insert(0,str(B));from geometry_core import compare
x=json.loads((B/'results.json').read_text());plt.rcParams.update({'font.family':'Times New Roman','font.size':11})
def load(uid):return np.load(B/'inputs'/f'{uid}.npz')['mask']
def norm(a):
 y,z=np.where(a);a=a[y.min():y.max()+1,z.min():z.max()+1];return cv2.resize(a.astype('uint8'),(max(1,round(a.shape[1]*48/a.shape[0])),48),interpolation=cv2.INTER_NEAREST).astype(bool)
selected=[max([r for r in x['words'] if r['writer']=='abhinav' and r['token']==t],key=lambda r:r['word_height_F']) for t in ['of','the']]+[x['summary']['thiya']['best_word_height']]
fig,axes=plt.subplots(3,3,figsize=(10,6),layout='constrained')
for j,r in enumerate(selected):
 a=norm(load(r['word_height_reference']));b=norm(load(r['id']));_,m=compare(a,b,True)
 for i,v in enumerate([a,b]):axes[i,j].imshow(~v,cmap='gray',vmin=0,vmax=1);axes[i,j].axis('off')
 axes[0,j].set_title(f"{r['writer'].capitalize()}: {r['token']}\nOriginal",fontsize=12);axes[1,j].set_title('Physical robot output',fontsize=11)
 aa=m['original_skeleton'];bb=m['physical_skeleton'];rgb=np.ones((*aa.shape,3));rgb[aa]=[.87,.31,.15];rgb[bb]=[.08,.38,.75];rgb[aa&bb]=[.35,.15,.55];yy,xx=np.where(aa|bb);axes[2,j].imshow(rgb[yy.min()-4:yy.max()+5,xx.min()-4:xx.max()+5]);axes[2,j].axis('off');axes[2,j].set_title(f"F {100*r['word_height_F']:.2f}%",fontsize=12,y=-.18)
fig.suptitle('Selected connected-word examples, separate word-height normalisation\nOrange original, blue robot, purple exact overlap',fontsize=13);fig.savefig(B/'figures/selected_connected_examples.png',dpi=200);fig.savefig(B/'figures/selected_connected_examples.pdf');plt.close(fig)
lines=['# Quick cursive and connected-word test, 2 November 2026','','The geometric comparison can be calculated on connected words without splitting characters. In this small test it produces strong matches for some partly connected Abhinav words, but does not establish strong overall matching for Thiya\'s fully cursive output.','','| Writer | Words | Prior line-x-height rule, mean F | Separate word-height normalisation, mean F | Best word-height example |','|---|---:|---:|---:|---|']
for w,z in x['summary'].items():
 r=z['best_word_height'];lines.append(f"| {w.capitalize()} | {z['words']} | {100*z['line_xheight_mean_F']:.2f}% | {100*z['word_height_mean_F']:.2f}% | {r['token']}, {100*r['word_height_F']:.2f}% |")
lines+=['','Five of Abhinav\'s 17 words exceed F = 0.85 under word-height normalisation. None of Thiya\'s eight do. No word exceeds 0.85 under the unchanged line-x-height rule. The word-height result is a separate diagnostic, not a replacement for the previous character experiment.','','## What was done','','Used the existing physical source-text word pairs, eight Thiya and seventeen Abhinav, omitting Abhinav\'s single-letter a because this test concerns words. No per-character cuts or recognition models were used. Original same-word banks were selected from the existing personal dataset by page diversity and source order, with up to eight references per word. Exact transcript tokens were retained, including case and punctuation. There were 201 candidate reference entries from 112 relevant source lines plus earlier fixed references. One hundred bank entries were selected before scoring. Two with obvious foreign ink were excluded after visual review, before scores. Some entries are different cached representations of the same source occurrence, so bank counts are not counts of independent handwritten words.','','The primary calculation preserves the previous 48-pixel line x-height, isotropic scaling, bounded translation of five pixels and nearest-centreline F-score within 4.8 pixels. Each physical word takes its best score within its fixed original bank. There is no width stretching, slant correction or deformable alignment. Because whole words retain spacing and join geometry, these word averages are not directly comparable with the earlier per-character means.','','The separate diagnostic tightly crops each word and scales its own total ink height to 48 pixels, preserving its aspect ratio. It uses the same five-pixel translation limit and a 4.8-pixel distance tolerance, now relative to total word height rather than line x-height. It independently chooses the best reference from the same fixed bank. It removes absolute word-height differences and changes the physical meaning of the tolerance, so the two columns must remain separately labelled.','','Whole-word overlays show differences in relative size, character spacing and joins. These are possible contributors to low overlap. This test does not isolate the contributions of normalisation, glyph extraction, synthesis or gantry motion. Letter splitting in fully connected writing has not been validated, so no cursive per-character accuracy is claimed.','','## Saved evidence','','figures/selected_connected_examples.png and its PDF show Abhinav of and the, and Thiya but. Their diagnostic scores are 96.16%, 86.47% and 71.14%. These examples were selected after scoring. Per-writer connected_words images show strongest, middle-ranked and weakest primary cases. All 25 word results and all bank comparisons are retained in results.json. word_scores.csv provides the concise numerical table.','','quick_cursive_test.py regenerates scores and per-writer figures from inputs/. finalise_cursive.py regenerates the selected gallery, these notes and the evidence ZIP. The frozen source/segment.py supplies the same image toolkit. The preparation script requires the original repository and caches, while numerical regeneration uses the saved masks. Dependencies are numpy, scipy, pillow, opencv-python and matplotlib. The point-distance F definition is the same as in the previous study, based on the Tanks and Temples tutorial Appendix B, https://tanksandtemples.org/tutorial/. The word-height diagnostic is an exploratory project choice.','','No report LaTeX, application code, model weights or hardware was changed. The earlier five-writer study and its package remain unchanged. This is an offline exploratory check, not an ODROID measurement or proof of the proposal requirements.']
(B/'FINDINGS.md').write_text('\n'.join(lines)+'\n',encoding='utf8');shutil.copy2(ROOT/'tmp/quick_cursive_prepare.py',B/'prepare_cursive_inputs.py');OUT=ROOT/'output';shutil.copy2(B/'FINDINGS.md',OUT/'Handwriting_Cursive_Quick_Test_2026-11-02.md')
files=[p for p in B.rglob('*') if p.is_file() and '__pycache__' not in p.parts and p.name!='ARCHIVE_MANIFEST.json'];(B/'ARCHIVE_MANIFEST.json').write_text(json.dumps({p.relative_to(B).as_posix():hashlib.sha256(p.read_bytes()).hexdigest() for p in files},indent=2))
with zipfile.ZipFile(OUT/'Handwriting_Cursive_Quick_Test_2026-11-02.zip','w',zipfile.ZIP_DEFLATED) as z:
 for p in files+[B/'ARCHIVE_MANIFEST.json']:z.write(p,p.relative_to(B))
print('Saved cursive test, figures and evidence archive')
